:OUT C:\Users\EstebanDemarco\Desktop\Vocaturo\muhle-vct\_diag\DIAG_TABLERO_PROYECTOS.txt
/* ============================================================================
   DIAG_TABLERO_PROYECTOS (29/10/2026)  solo lectura
   Por que en Mis proyectos del tablero no salen servicios, normas ni analista:
   1) marcas DASH_TAB_V7 / V8 en la definicion viva de VCT_MAIN_DASHBOARD
   2) para los proyectos 1348, 1312, 1268, 1257: filas de servicios, normas y equipo + las expresiones del tablero
   3) vuelca dbo.VCT_MAIN_PROYECTOS a _diag\VCT_MAIN_PROYECTOS.txt (para copiar su criterio)
   SSMS: Query > SQLCMD Mode, F5.
   ============================================================================ */
USE [MuhlePROD];
SET NOCOUNT ON;
DECLARE @D NVARCHAR(MAX) = OBJECT_DEFINITION(OBJECT_ID('dbo.VCT_MAIN_DASHBOARD'));
PRINT '== 1. marcas ==';
SELECT CASE WHEN CHARINDEX('DASH_TAB_V7', @D) > 0 THEN 'SI' ELSE 'NO' END AS V7, CASE WHEN CHARINDEX('DASH_TAB_V8', @D) > 0 THEN 'SI' ELSE 'NO' END AS V8,
       CASE WHEN CHARINDEX('vct-tablero.js?v=8', @D) > 0 THEN 'v8' WHEN CHARINDEX('vct-tablero.js?v=7', @D) > 0 THEN 'v7' ELSE 'otra' END AS JS;
PRINT '== 2a. proyectos (codigo -> id) ==';
SELECT P.ID, P.CODIGO, P.NOMBRE FROM dbo.VCT_PROYECTOS P WITH(NOLOCK) WHERE CONVERT(VARCHAR(50), P.CODIGO) IN ('1348','1312','1268','1257') OR P.ID IN (1348,1312,1268,1257);
PRINT '== 2b. servicios ==';
SELECT XS.ID_PROYECTO, XS.ID, XS.ID_SERVICIO, S.CODIGO, S.DESCRIPCION FROM dbo.VCT_PROYECTOS_SERVICIOS XS WITH(NOLOCK) LEFT JOIN dbo.VCT_PRM_SERVICIOS S WITH(NOLOCK) ON S.ID = XS.ID_SERVICIO
WHERE XS.ID_PROYECTO IN (SELECT P.ID FROM dbo.VCT_PROYECTOS P WHERE CONVERT(VARCHAR(50), P.CODIGO) IN ('1348','1312','1268','1257') OR P.ID IN (1348,1312,1268,1257));
PRINT '== 2c. normas ==';
SELECT PN.*, N.DESCRIPCION FROM dbo.VCT_PROYECTOS_NORMAS PN WITH(NOLOCK) LEFT JOIN dbo.VCT_PRM_NORMAS N WITH(NOLOCK) ON N.ID = PN.ID_NORMA
WHERE PN.ID_PROYECTO IN (SELECT P.ID FROM dbo.VCT_PROYECTOS P WHERE CONVERT(VARCHAR(50), P.CODIGO) IN ('1348','1312','1268','1257') OR P.ID IN (1348,1312,1268,1257))
   OR PN.ID_PROYECTO_SERVICIO IN (SELECT XS.ID FROM dbo.VCT_PROYECTOS_SERVICIOS XS WHERE XS.ID_PROYECTO IN (SELECT P.ID FROM dbo.VCT_PROYECTOS P WHERE CONVERT(VARCHAR(50), P.CODIGO) IN ('1348','1312','1268','1257') OR P.ID IN (1348,1312,1268,1257)));
PRINT '== 2d. equipo (empleados) ==';
SELECT EQ.ID_PROYECTO, EQ.TIPO_MIEMBRO, EQ.ID_EMPLEADO, EQ.ID_ROL, R.CODIGO AS ROL, EQ.ESTADO, E.APELLIDOS, E.NOMBRES FROM dbo.VCT_PROYECTOS_EQUIPO EQ WITH(NOLOCK)
LEFT JOIN dbo.VCT_PRM_PROYECTOS_ROLES R WITH(NOLOCK) ON R.ID = EQ.ID_ROL LEFT JOIN dbo.VCT_EMPLEADOS E WITH(NOLOCK) ON E.ID = EQ.ID_EMPLEADO
WHERE EQ.ID_PROYECTO IN (SELECT P.ID FROM dbo.VCT_PROYECTOS P WHERE CONVERT(VARCHAR(50), P.CODIGO) IN ('1348','1312','1268','1257') OR P.ID IN (1348,1312,1268,1257)) AND EQ.TIPO_MIEMBRO <> 'CONSULTOR';
PRINT '== 2e. expresiones del tablero ==';
SELECT P.ID, P.CODIGO, ISNULL(STUFF((SELECT DISTINCT ',' + CASE WHEN UPPER(ISNULL(S.CODIGO, '') + ' ' + ISNULL(S.DESCRIPCION, '')) LIKE '%AUDIT%' THEN 'AU' WHEN UPPER(ISNULL(S.CODIGO, '') + ' ' + ISNULL(S.DESCRIPCION, '')) LIKE '%CAPACIT%' THEN 'CA' WHEN UPPER(ISNULL(S.CODIGO, '') + ' ' + ISNULL(S.DESCRIPCION, '')) LIKE '%CONSULT%' THEN 'CO' ELSE 'XX' END FROM dbo.VCT_PROYECTOS_SERVICIOS XS WITH(NOLOCK) INNER JOIN dbo.VCT_PRM_SERVICIOS S WITH(NOLOCK) ON S.ID = XS.ID_SERVICIO WHERE XS.ID_PROYECTO = P.ID FOR XML PATH(''), TYPE).value('.', 'VARCHAR(200)'), 1, 1, ''), '') AS SVCS, ISNULL(STUFF((SELECT '|' + ISNULL(N.DESCRIPCION, '') FROM dbo.VCT_PROYECTOS_NORMAS PN WITH(NOLOCK) INNER JOIN dbo.VCT_PRM_NORMAS N WITH(NOLOCK) ON N.ID = PN.ID_NORMA WHERE PN.ID_PROYECTO = P.ID AND UPPER(ISNULL(PN.ESTADO, '')) NOT LIKE 'INACTIV%' AND UPPER(ISNULL(PN.ESTADO, '')) NOT IN ('BAJA', 'ANULADA', 'ANULADO', 'ELIMINADA', 'ELIMINADO') GROUP BY N.DESCRIPCION ORDER BY N.DESCRIPCION FOR XML PATH(''), TYPE).value('.', 'VARCHAR(2000)'), 1, 1, ''), '') AS NORMAS, (SELECT TOP 1 UPPER(LEFT(LTRIM(ISNULL(E.NOMBRES, '')), 1) + LEFT(LTRIM(ISNULL(E.APELLIDOS, '')), 1)) FROM dbo.VCT_PROYECTOS_EQUIPO EQ WITH(NOLOCK) INNER JOIN dbo.VCT_EMPLEADOS E WITH(NOLOCK) ON E.ID = EQ.ID_EMPLEADO INNER JOIN dbo.VCT_PRM_PROYECTOS_ROLES R WITH(NOLOCK) ON R.ID = EQ.ID_ROL WHERE EQ.ID_PROYECTO = P.ID AND R.CODIGO = 'ANALISTA' AND ISNULL(EQ.ESTADO, 'ACTIVO') = 'ACTIVO' ORDER BY EQ.ID_EMPLEADO) AS AN_INI, (SELECT TOP 1 LTRIM(RTRIM(ISNULL(E.APELLIDOS, '') + CASE WHEN ISNULL(E.NOMBRES, '') <> '' THEN ', ' + E.NOMBRES ELSE '' END)) FROM dbo.VCT_PROYECTOS_EQUIPO EQ WITH(NOLOCK) INNER JOIN dbo.VCT_EMPLEADOS E WITH(NOLOCK) ON E.ID = EQ.ID_EMPLEADO INNER JOIN dbo.VCT_PRM_PROYECTOS_ROLES R WITH(NOLOCK) ON R.ID = EQ.ID_ROL WHERE EQ.ID_PROYECTO = P.ID AND R.CODIGO = 'ANALISTA' AND ISNULL(EQ.ESTADO, 'ACTIVO') = 'ACTIVO' ORDER BY EQ.ID_EMPLEADO) AS AN_NOM
FROM dbo.VCT_PROYECTOS P WITH(NOLOCK) WHERE CONVERT(VARCHAR(50), P.CODIGO) IN ('1348','1312','1268','1257') OR P.ID IN (1348,1312,1268,1257);
GO
:OUT C:\Users\EstebanDemarco\Desktop\Vocaturo\muhle-vct\_diag\VCT_MAIN_PROYECTOS.txt
USE [MuhlePROD];
SET NOCOUNT ON;
DECLARE @D NVARCHAR(MAX) = OBJECT_DEFINITION(OBJECT_ID('dbo.VCT_MAIN_PROYECTOS'));
IF @D IS NULL PRINT 'No se encontro dbo.VCT_MAIN_PROYECTOS.'
ELSE
BEGIN
    DECLARE @TOTAL INT = DATALENGTH(@D) / 2, @P INT = 1, @E INT, @LINE NVARCHAR(MAX);
    WHILE @P <= @TOTAL
    BEGIN
        SET @E = CHARINDEX(NCHAR(10), @D, @P);
        IF @E = 0 SET @E = @TOTAL + 1;
        SET @LINE = SUBSTRING(@D, @P, @E - @P);
        IF DATALENGTH(@LINE) > 0 AND RIGHT(@LINE, 1) = NCHAR(13) SET @LINE = SUBSTRING(@LINE, 1, (DATALENGTH(@LINE) / 2) - 1);
        WHILE (DATALENGTH(@LINE) / 2) > 4000
        BEGIN
            PRINT SUBSTRING(@LINE, 1, 4000);
            SET @LINE = SUBSTRING(@LINE, 4001, 1000000);
        END;
        PRINT @LINE;
        SET @P = @E + 1;
    END;
END;
GO
:OUT stdout
